<?php
session_start(); require '../database/config.php'; require '../includes/auth.php'; requireCustomer();
$pdo=getConnection(); $uid=(int)$_SESSION['user_id'];
$v=$pdo->prepare("SELECT vr.*,d.location,d.name FROM viewing_requests vr JOIN dormitories d ON d.id=vr.dormitory_id WHERE vr.user_id=:id ORDER BY vr.created_at DESC LIMIT 5"); $v->execute(['id'=>$uid]); $viewings=$v->fetchAll();
$a=$pdo->prepare("SELECT ra.*,r.room_number,r.room_type,d.location FROM room_applications ra JOIN rooms r ON r.id=ra.room_id JOIN dormitories d ON d.id=r.dormitory_id WHERE ra.user_id=:id ORDER BY ra.created_at DESC LIMIT 5"); $a->execute(['id'=>$uid]); $apps=$a->fetchAll();
$status=$_GET['status']??null; $message=$_GET['message']??null;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Account | Obeda Dormitories</title><link rel="stylesheet" href="../assets/css/customer.css"></head><body><header class="customer-header"><a href="../index.php"><img src="../assets/images/logo-dark.svg" alt="Obeda Dormitories"></a><nav><a class="active" href="dashboard.php">Dashboard</a><a href="viewing.php">Viewing</a><a href="rooms.php">Rooms</a><a href="application.php">My Applications</a><a href="profile.php">Profile</a></nav><div><span><?=h($_SESSION['first_name'])?></span><a href="../logout.php">Logout</a></div></header><main class="customer-main"><h1>Welcome, <?=h($_SESSION['first_name'])?></h1><?php if($message): ?><div class="alert <?= $status==='error'?'error':'success' ?>"><?=h($message)?></div><?php endif; ?><div class="cards"><section class="panel"><h2>My Viewing Requests</h2><?php foreach($viewings as $r): ?><div class="item"><strong><?=h($r['location'])?></strong><span><?=h($r['preferred_date'])?> at <?=h(substr($r['preferred_time'],0,5))?></span><span class="status <?=h($r['status'])?>"><?=h(ucfirst($r['status']))?></span></div><?php endforeach; if(!$viewings): ?><p>No viewing requests yet.</p><?php endif; ?><a class="button" href="viewing.php">Schedule a Viewing</a></section><section class="panel"><h2>My Room Applications</h2><?php foreach($apps as $r): ?><div class="item"><strong><?=h($r['location'])?> / Room <?=h($r['room_number'])?></strong><span><?=h($r['move_in_date']?:'No move-in date')?></span><span class="status <?=h($r['status'])?>"><?=h(ucfirst($r['status']))?></span></div><?php endforeach; if(!$apps): ?><p>No room applications yet.</p><?php endif; ?><a class="button" href="rooms.php">View Available Rooms</a></section></div></main></body></html>
